// <work-model> — the themed wrapper over Google's <model-viewer>.
//
// 3D's analogue of <work-video>: the floor VIEWER for glTF/GLB/STL. model-viewer
// (Apache-2.0) is itself a custom element built on three.js; we do NOT reimplement
// any of it. We wrap it in a token-themed shell — frame chrome, our own loading /
// error / placeholder states, and model-viewer's OWN CSS custom properties driven
// from --work-* tokens — all shadow-scoped, exactly like the video wrapper.
//
// LAZY LOAD (mirrors plot-tier / wavelet runtime-src): model-viewer is imported
// from a CDN ESM at first connect — nothing is bundled, no dep installed. The
// single-flight loader is overridable via `window.__WB_MODELVIEWER__` (tests /
// offline hosts inject their own, OR set it falsy to force the floor). If the
// import fails (network-blocked — the gate-c wasm/floor proof) OR no `src` is set,
// we render a THEMED PLACEHOLDER CARD with the model name + a typed glyph (never a
// blank box).
//
// THEMING (gate-a, token-leak): model-viewer paints its progress bar / poster /
// AR button / interaction prompt from its OWN `--poster-color`, `--progress-bar-*`,
// `--mv-*` custom properties. We set every one of those from --work-* tokens so
// the viewer chrome re-themes light/dark/signal. The model's own materials keep
// their authored pixels (preview ≡ render of the asset) — we theme the CHROME, not
// the geometry, mirroring the video stage.
//
// SCOPE (gate-b): the <model-viewer> element + its shadow live INSIDE this
// element's shadow root; its styles never land in document.head.
//
// Usage:
//   <work-model src="astronaut.glb" camera-controls auto-rotate></work-model>
//   <work-model src="model.glb" ar poster="poster.webp"></work-model>
//   el.addEventListener("work-model-load", …); // / "work-model-error"
//
// Generation (text/image → 3D) is HOST-BROKERED — see `generate()` below: the seam
// routes to Meshy / Tripo through `this.host` (a `/3d/generate` Dock verb). We
// document the seam and degrade gracefully; no live key is wired here.

import { WbElement, html, css, define } from "../../core/element.js";
import { defineVariants, variantAttrs } from "../../core/variants.js";

// Default CDN for model-viewer's ESM bundle. Override per-element with
// `viewer-src`, or globally / for tests via window.__WB_MODELVIEWER__. Set
// __WB_MODELVIEWER__ to a falsy non-undefined value (e.g. null via a flag) to
// force the floor placeholder without a network hit.
const DEFAULT_VIEWER_SRC = "https://esm.sh/@google/model-viewer@4.0.0";

// One in-flight import shared across every <work-model> on the page. Resolves once
// <model-viewer> is registered. Rejects (→ floor placeholder) when the chunk can't
// load. An explicit window.__WB_MODELVIEWER__ override short-circuits the import:
//   • a truthy value → treat as "already provided" (e.g. a host that pre-bundled it),
//   • `false`/`null` (the key EXISTS but is falsy) → force the floor (no import).
let _viewerLoad = null;
function loadModelViewer(rawSrc) {
  // explicit override present?
  if (typeof window !== "undefined" && "__WB_MODELVIEWER__" in window) {
    const ov = window.__WB_MODELVIEWER__;
    if (!ov) return Promise.reject(new Error("model-viewer disabled (__WB_MODELVIEWER__ falsy)"));
    return Promise.resolve(true);
  }
  // already registered by the host?
  if (typeof customElements !== "undefined" && customElements.get("model-viewer")) {
    return Promise.resolve(true);
  }
  let src = rawSrc;
  try {
    if (typeof document !== "undefined") src = new URL(rawSrc, document.baseURI).href;
  } catch { /* keep rawSrc */ }
  if (!_viewerLoad) {
    _viewerLoad = import(/* @vite-ignore */ src).then(
      () => true,
      (e) => { _viewerLoad = null; throw e; }, // allow a later retry
    );
  }
  return _viewerLoad;
}

const VARIANTS = defineVariants({
  // visual weight of the viewer frame (matches work-video's transport vocabulary)
  variant: { options: ["solid", "soft", "bare"], default: "solid" },
  size: { options: ["sm", "md", "lg"], default: "md" },
  // accent the chrome (progress bar, AR button) paints with
  tone: { options: ["brand", "neutral"], default: "brand" },
});

export class WorkModel extends WbElement {
  static variants = VARIANTS;
  static props = [
    ...variantAttrs(VARIANTS),
    "src",        // glTF / GLB / STL URL
    "poster",     // still shown until the model loads
    "alt",        // accessible description
    "ar",         // present → enable WebXR / Scene Viewer / Quick Look
    "auto-rotate",
    "camera-controls",
    "name",       // label for the floor placeholder
    "viewer-src", // override the model-viewer ESM URL
  ];

  static styles = css`
    :host { display: block; color: var(--work-fg); font-family: var(--work-font); }

    .frame {
      position: relative;
      display: flex; flex-direction: column;
      background: var(--work-surface);
      border: 1.5px solid var(--work-border);
      border-radius: var(--work-radius-lg);
      overflow: hidden;
      box-shadow: var(--work-shadow);
      aspect-ratio: 4 / 3;
    }
    :host([variant="soft"]) .frame { background: var(--work-surface-soft); box-shadow: var(--work-shadow-sm); }
    :host([variant="bare"]) .frame { background: transparent; border-color: transparent; box-shadow: none; border-radius: var(--work-radius); }
    :host([size="sm"]) .frame { aspect-ratio: 1 / 1; }
    :host([size="lg"]) .frame { aspect-ratio: 16 / 9; }

    /* the embedded <model-viewer>: fills the frame; its chrome is driven from
       --work-* tokens. The stage backdrop is a soft surface so light/dark/signal
       all read (the geometry itself keeps its authored materials). */
    model-viewer {
      flex: 1 1 auto; min-height: 0; width: 100%; height: 100%;
      display: block;
      background:
        radial-gradient(120% 120% at 30% 18%,
          var(--work-surface-soft) 0%, var(--work-surface) 72%);
      /* model-viewer's own theming hooks — all from tokens, zero literal leak */
      --poster-color: var(--work-surface);
      --progress-bar-color: var(--_a);
      --progress-bar-height: 3px;
      --progress-mask: transparent;
      --mv-interaction-prompt-text-color: var(--work-fg-muted);
      --interaction-prompt-color: var(--work-fg-muted);
      --_a: var(--work-brand);
    }
    :host([tone="neutral"]) model-viewer { --_a: var(--work-fg); }

    /* AR button, themed from tokens */
    model-viewer .ar-btn {
      position: absolute; right: var(--work-space-3); bottom: var(--work-space-3);
      appearance: none; cursor: pointer;
      height: 32px; padding: 0 var(--work-space-3);
      display: inline-flex; align-items: center; gap: var(--work-space-2);
      border: 1.5px solid var(--work-border-strong);
      border-radius: var(--work-radius-pill);
      background: var(--work-surface); color: var(--_a);
      font: 600 var(--work-text-sm) / 1 var(--work-font);
    }
    model-viewer .ar-btn:hover { background: var(--work-brand-soft); border-color: var(--_a); }

    /* loading + error chrome (token only) */
    .status {
      position: absolute; inset: 0;
      display: grid; place-items: center; padding: var(--work-space-4);
      text-align: center;
      color: var(--work-fg-muted); font-size: var(--work-text-sm);
      font-family: var(--work-font-mono);
    }
    .status.err { color: var(--work-err); white-space: pre-wrap; }

    /* the FLOOR placeholder — shown when there is no model-viewer (blocked /
       disabled) or no src. A clean themed card with a typed glyph + the name,
       never a blank box. */
    .floor {
      position: absolute; inset: 0;
      display: flex; flex-direction: column; align-items: center; justify-content: center;
      gap: var(--work-space-3); padding: var(--work-space-5);
      text-align: center;
      background:
        radial-gradient(120% 120% at 30% 18%,
          var(--work-surface-soft) 0%, var(--work-surface) 72%);
    }
    .floor .glyph {
      font-size: var(--work-glyph-lg);
      line-height: 1;
      color: var(--_a, var(--work-brand));
      filter: drop-shadow(0 2px 10px var(--work-brand-soft));
    }
    :host([tone="neutral"]) .floor { --_a: var(--work-fg); }
    .floor .name {
      font: 600 var(--work-text) / 1.2 var(--work-font);
      color: var(--work-fg);
      word-break: break-word;
    }
    .floor .hint {
      font: 400 var(--work-text-sm) / 1.4 var(--work-font);
      color: var(--work-fg-subtle);
      max-width: 36ch;
    }
  `;

  constructor() {
    super();
    this._mvReady = false;   // model-viewer registered (import resolved)
    this._mvFailed = false;  // import failed / disabled → floor
    this._loading = false;   // a model is currently loading
    this._error = null;      // load error message
  }

  connectedCallback() {
    super.connectedCallback();
    this._ensureViewer();
    this._resolveSource();
  }

  /** Resolve a child <work-model-source> (composition-as-source) into `src`. A
   *  direct `src` attr always wins; otherwise a source child's compile() result
   *  drives the viewer (a `src` form sets it directly; a stubbed `code` form
   *  surfaces a clear status instead of a wrong model). */
  async _resolveSource() {
    if (this.attr("src")) return; // explicit src wins
    const srcEl = this.querySelector("work-model-source");
    if (!srcEl?.compile) return;
    try {
      const out = await srcEl.compile();
      if (out?.url) this.setAttribute("src", out.url);
      else if (out?.pending) { this._error = out.note; this.requestUpdate(); }
    } catch (e) { this._onError({ detail: { type: String(e?.message || e) } }); }
  }

  attributeChangedCallback(name, oldV, newV) {
    super.attributeChangedCallback(name, oldV, newV);
    if (!this.isConnected) return;
    if (name === "viewer-src" && oldV !== newV) {
      this._mvReady = this._mvFailed = false;
      this._ensureViewer();
    }
    if (name === "src" && oldV !== newV) {
      this._error = null;
      this._loading = !!newV && this._mvReady;
    }
  }

  /** Lazy-load model-viewer; on success render the real viewer, on failure the floor. */
  async _ensureViewer() {
    const viewerSrc = this.attr("viewer-src", DEFAULT_VIEWER_SRC);
    try {
      await loadModelViewer(viewerSrc);
      this._mvReady = true;
      this._mvFailed = false;
      this._loading = !!this.attr("src");
    } catch {
      this._mvReady = false;
      this._mvFailed = true; // → floor placeholder (graceful degrade)
    }
    this.requestUpdate();
  }

  // ---- model-viewer event bridge → themed `work-model-*` events ----------

  _onLoad() {
    this._loading = false;
    this._error = null;
    this.requestUpdate();
    this.dispatchEvent(new CustomEvent("work-model-load", {
      bubbles: true, composed: true, detail: { src: this.attr("src") },
    }));
  }

  _onError(e) {
    this._loading = false;
    this._error = e?.detail?.type || "failed to load model";
    this.requestUpdate();
    this.dispatchEvent(new CustomEvent("work-model-error", {
      bubbles: true, composed: true, detail: { src: this.attr("src"), error: this._error },
    }));
  }

  // ---- generation seam (text/image → 3D) — HOST-BROKERED -----------------

  /**
   * Generate a model from a text prompt (or an image) via the Host broker — the
   * runtime proxies Meshy / Tripo (so the key stays host-side; never in the
   * artifact). On success the returned GLB url is set as `src`. Degrades cleanly
   * when no 3D capability is granted.
   *
   *   await el.generate({ prompt: "a low-poly fox" });
   *   await el.generate({ image: blobUrl });
   */
  async generate({ prompt, image, provider } = {}) {
    if (!this.host?.available?.("3d")) {
      this.dispatchEvent(new CustomEvent("work-model-error", {
        bubbles: true, composed: true,
        detail: { error: "3D generation needs a host broker (Meshy/Tripo) — not available" },
      }));
      return null;
    }
    this._loading = true; this._error = null; this.requestUpdate();
    try {
      const out = await this.host.request("/3d/generate", { body: { prompt, image, provider } });
      if (out?.url) this.setAttribute("src", out.url);
      return out;
    } catch (e) {
      this._onError({ detail: { type: String(e?.message || e) } });
      return null;
    }
  }

  // ---- render -------------------------------------------------------------

  render() {
    const src = this.attr("src");
    const a = this.constructor; void a;

    // FLOOR: no viewer engine (blocked / disabled), or nothing to show.
    if (this._mvFailed || (!this._mvReady && !src) || (this._mvReady && !src)) {
      return html`<div class="frame">${this._floor(src)}</div>`;
    }
    // still importing the engine
    if (!this._mvReady) {
      return html`<div class="frame"><div class="status">Loading 3D viewer…</div></div>`;
    }

    const poster = this.attr("poster");
    const alt = this.attr("alt") || this.attr("name") || "3D model";
    const ar = this.boolAttr("ar");
    const autoRotate = this.boolAttr("auto-rotate");
    const cameraControls = this.boolAttr("camera-controls");

    // The real <model-viewer>, themed via tokens (see static styles). We forward
    // the boolean/feature attrs and bridge its load/error to work-model-* events.
    return html`<div class="frame">
      <model-viewer
        src=${src}
        alt=${alt}
        ?ar=${ar}
        ?auto-rotate=${autoRotate}
        ?camera-controls=${cameraControls}
        poster=${poster || ""}
        exposure="1"
        shadow-intensity="0.9"
        @load=${() => this._onLoad()}
        @error=${(e) => this._onError(e)}
      >
        ${ar ? html`<button slot="ar-button" class="ar-btn">View in AR</button>` : ""}
      </model-viewer>
      ${this._error ? html`<div class="status err">3D: ${this._error}</div>` : ""}
    </div>`;
  }

  /** Themed placeholder card — typed glyph + the model name. Never blank. */
  _floor(src) {
    const name = this.attr("name") ||
      (src ? src.split("/").pop() : "3D model");
    const hint = this._mvFailed
      ? "3D viewer unavailable — showing the model reference."
      : src
        ? "Preparing the 3D viewer…"
        : "No model. Set the src attribute to a glTF / GLB / STL URL.";
    return html`<div class="floor">
      <div class="glyph" aria-hidden="true">◈</div>
      <div class="name">${name}</div>
      <div class="hint">${hint}</div>
    </div>`;
  }
}

define("work-model", WorkModel);

// WbElement — the base for every <wb-*> element, re-based onto Lit.
//
// Lit is the FLOOR's engine now (the approved adoption pass): surgical template
// updates instead of an innerHTML nuke, while every workponents convention is
// preserved so the rest of the library migrates mechanically. Lit is loaded as a
// bare specifier ("lit") — buildless via an import map in the demos, a peer dep
// for SDK consumers (see README / demo/lit-foundation.html). No bundler, no
// `bun install`.
//
// Conventions (unchanged — the whole library follows these):
//   • Shadow DOM (open) for style isolation; --work-* tokens inherit through it.
//   • `static styles` = the component CSS as a Lit `css``` CSSResult (was a
//     string). Use ONLY var(--work-*). Variants targeted via :host([name="value"]).
//   • `render()` returns a Lit `html``` TemplateResult (was a string) — surgical
//     updates, no innerHTML rewrite.
//   • `static props` = reflected attributes that re-render on change (variants,
//     state). They are mapped to Lit reactive properties automatically.
//   • `static variants` defaults are reflected on connect (before first paint) so
//     :host([name="value"]) selectors always match.
//   • Capability is reached through `this.host` (the Dock seam), never hardcoded.
//   • Register with `define()` (idempotent — safe to load twice).
//
// `attr()` / `boolAttr()` helpers are preserved for elements that read attributes
// directly in render(). Re-exports `html` + `css` so domain files import the whole
// authoring surface from one place:
//   import { WbElement, html, css, define } from "../core/element.js";

import { LitElement, html, css } from "lit";
import { getHost } from "./host.js";

export { html, css };

export class WbElement extends LitElement {
  /** @type {import("lit").CSSResult} component CSS — override with css``; use only var(--work-*) */
  static styles = css``;

  /** @type {string[]} reflected attributes that trigger a re-render */
  static props = [];

  // Register each subclass's `static props` as Lit reactive properties so an
  // attribute change fires attributeChangedCallback + re-renders (the old
  // observedAttributes contract). NOTE: a base-class `static get properties()` is
  // NOT honored — Lit's finalize() only reads each class's OWN `properties`. So we
  // hook finalize() and createProperty() per subclass instead. Reflect ONLY the
  // short variant enums (so el.variant = "soft" still matches :host([variant]));
  // never reflect data attributes like `rows`/`csv`/`query` (can be huge strings).
  static finalize() {
    super.finalize();
    const variants = this.variants || {};
    for (const name of this.props || []) {
      const key = this._propKey(name);
      // Skip names that already exist on the prototype as a method/getter (e.g. a
      // `variant(name)` helper, an `open()` method). Creating a reactive accessor
      // there THROWS in Lit dev mode ("declared as a reactive property but it's
      // actually declared as a value on the prototype"). The attribute is still
      // OBSERVED via observedAttributes below, so attribute changes still fire
      // attributeChangedCallback → the element's reload/requestUpdate runs.
      if (key in this.prototype) continue;
      this.createProperty(key, {
        type: String,
        attribute: name,
        reflect: Object.prototype.hasOwnProperty.call(variants, name),
      });
    }
  }

  // Guarantee every `static props` attribute is OBSERVED (the browser reads this
  // at customElements.define() time). This is the bulletproof half: even if Lit's
  // reactive-property finalize timing misses one, attribute changes still fire
  // attributeChangedCallback → the element's reload/requestUpdate handler runs.
  static get observedAttributes() {
    const base = super.observedAttributes || [];
    return Array.from(new Set([...base, ...(this.props || [])]));
  }

  // Attribute names may contain dashes; reactive-property keys must be identifiers.
  static _propKey(name) {
    return name.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
  }

  /** The Dock/Host capability seam — local | runtime (RCP) | kernel. */
  get host() {
    return getHost();
  }

  /** Read an attribute with a default. */
  attr(name, fallback = null) {
    return this.hasAttribute(name) ? this.getAttribute(name) : fallback;
  }

  /** Read a boolean attribute (present = true). */
  boolAttr(name) {
    return this.hasAttribute(name);
  }

  /** Override: return the template (Lit `html```). */
  render() {
    return html`<slot></slot>`;
  }

  connectedCallback() {
    // Reflect default variants BEFORE Lit's first render so :host([name="value"])
    // selectors match the very first paint, even when the author sets only some
    // (e.g. tone without variant).
    const v = this.constructor.variants;
    if (v) {
      for (const [name, def] of Object.entries(v)) {
        if (!this.hasAttribute(name)) this.setAttribute(name, def.default);
      }
    }
    super.connectedCallback();
  }
}

/** Idempotent custom-element registration (safe across double-loads). */
export function define(name, ctor) {
  if (!customElements.get(name)) customElements.define(name, ctor);
  return ctor;
}

// The Host/Dock seam — one capability surface for every element.
//
// A workponent never hardcodes where a capability runs. It asks the Host, which
// resolves `local` (in-WASM / browser-native), `runtime` (a Workbooks runtime
// over RCP), or `kernel` (oql.wasm) per the platform-model — so the SAME element
// (e.g. <wb-table>) runs in-WASM locally or on the runtime tier for huge data,
// no code fork. Capability elements declare what they need; the Host provisions
// it (the same grant model toolkits use) and reports availability so the element
// degrades cleanly when a capability is absent (e.g. voice without a key).
//
// Phase 0: a minimal, portable seam (no Tauri/Svelte). When a runtime URL is
// configured it routes over fetch/WebSocket (mirroring desktop/src/lib/rcp);
// otherwise it serves local capabilities and reports the rest unavailable.

let _host = null;

export class WbHost {
  /** @param {{ runtimeUrl?: string|null, tenant?: string }} [opts] */
  constructor(opts = {}) {
    this.runtimeUrl = opts.runtimeUrl || null;
    this.tenant = opts.tenant || "local";
    this._caps = new Set(["local"]); // in-WASM/browser caps are always present
  }

  /** Is a capability reachable here? (elements gate UI on this) */
  available(cap) {
    return this._caps.has(cap) || (this.runtimeUrl != null && cap !== "voice");
  }

  /** Unary capability call — routed to the runtime when present. */
  async request(path, { method = "POST", body } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const res = await fetch(this.runtimeUrl.replace(/\/$/, "") + path, {
      method,
      headers: { "content-type": "application/json", "x-tenant": this.tenant },
      body: body != null ? JSON.stringify(body) : undefined,
    });
    if (!res.ok) throw new Error(`wb-host ${res.status} ${path}`);
    return res.json();
  }

  /** Streaming capability — a WebSocket to the runtime. */
  socket(path, { onMessage } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const url = this.runtimeUrl.replace(/^http/, "ws").replace(/\/$/, "") + path;
    const ws = new WebSocket(url);
    if (onMessage) ws.addEventListener("message", (e) => onMessage(e.data));
    return ws;
  }
}

/** Configure the shared Host (call once at app/workbook boot). */
export function configureHost(opts) {
  _host = new WbHost(opts);
  return _host;
}

/** The shared Host singleton (a local-only Host by default). */
export function getHost() {
  if (!_host) {
    // Honor a global hint (a workbook/desktop can set window.__WB_RUNTIME_URL__).
    const url = typeof window !== "undefined" ? window.__WB_RUNTIME_URL__ : null;
    _host = new WbHost({ runtimeUrl: url || null });
  }
  return _host;
}

// Variants — the cva-style contract for web components.
//
// Variants are REFLECTED ATTRIBUTES the component CSS targets via :host([...]).
// This util doesn't generate classes; it (1) declares the allowed values +
// defaults for an element (so authoring is typed/validated and the design-lint
// can check conformance), and (2) normalizes the live attribute, applying the
// default when unset or invalid. The actual styling lives in the component CSS:
//
//   static styles = `
//     :host([variant="solid"]) button { background: var(--work-brand); }
//     :host([size="sm"])      button { padding: var(--work-space-1) var(--work-space-2); }
//   `;
//
// Usage in an element:
//   static variants = defineVariants({
//     variant: { options: ["solid", "soft", "ghost"], default: "solid" },
//     size:    { options: ["sm", "md", "lg"],        default: "md" },
//     tone:    { options: ["brand", "neutral", "ok", "warn", "err"], default: "brand" },
//   });
//   // in render(): this.variant("variant") -> the resolved value

export function defineVariants(spec) {
  return spec;
}

/** Resolve a variant attribute on `el` to a valid value (default on miss). */
export function resolveVariant(el, spec, name) {
  const def = spec[name];
  if (!def) return el.getAttribute(name);
  const v = el.getAttribute(name);
  return def.options.includes(v) ? v : def.default;
}

/** Every variant attribute name an element declares (for observedAttributes). */
export function variantAttrs(spec) {
  return Object.keys(spec || {});
}

/** Design-lint helper: report any variant attr set to a non-allowed value. */
export function lintVariants(el, spec) {
  const bad = [];
  for (const [name, def] of Object.entries(spec || {})) {
    const v = el.getAttribute(name);
    if (v != null && !def.options.includes(v)) bad.push({ name, value: v, allowed: def.options });
  }
  return bad;
}
